def gen(rng):
    def f(a, target):
        return '%d %d\n%s' % (len(a), target, ' '.join(map(str, a)))

    def count(a, target):
        a = sorted(a)
        n = len(a)
        c = 0
        for i in range(n - 2):
            if i and a[i] == a[i - 1]:
                continue
            need = target - a[i]
            l, r = i + 1, n - 1
            while l < r:
                s = a[l] + a[r]
                if s < need:
                    l += 1
                elif s > need:
                    r -= 1
                else:
                    c += 1
                    lv, rv = a[l], a[r]
                    while l < r and a[l] == lv:
                        l += 1
                    while l < r and a[r] == rv:
                        r -= 1
        return c

    tests = [f([5], 5), f([1, 2], 3), f([1, 2, 3], 6), f([1, 2, 3], 7), f([0, 0, 0, 0], 0), f([2, 2, 2, 3], 6),
             f([3, 1, 5, 4, 2, 6], 9), f([-1, 0, 1, 2, -1, -4, 1], 0), f([10 ** 6, 10 ** 6, 10 ** 6], 3 * 10 ** 6),
             f([-10 ** 6, -10 ** 6, -10 ** 6, 5], -3 * 10 ** 6)]
    for _ in range(70):
        n = rng.randint(1, 9)
        v = rng.choice([3, 5, 10])
        a = [rng.randint(-v, v) for _ in range(n)]
        tests.append(f(a, rng.randint(-v, v) if rng.random() < 0.5 else rng.randint(-2 * v, 2 * v)))
    n = 1000
    a = [rng.randint(-10 ** 6, 10 ** 6) for _ in range(n)]
    i, j, k = rng.sample(range(n), 3)
    tests.append(f(a, a[i] + a[j] + a[k]))
    a = list(range(-500, 500))
    rng.shuffle(a)
    for tg in (1500, 1200, 900, 600, 300, 0):
        if count(a, tg) <= 10 ** 5:
            tests.append(f(a, tg))
            break
    a = [rng.randint(-30, 30) for _ in range(n)]
    tests.append(f(a, 0))
    tests.append(f([0] * n, 0))
    a = [rng.randint(-1000, 1000) for _ in range(n)]
    for tg in (0, 500, 1500, 2500):
        if count(a, tg) <= 10 ** 5:
            tests.append(f(a, tg))
            break
    a = [rng.randint(-10 ** 6, 10 ** 6) for _ in range(n // 2)] + [rng.randint(-10 ** 6, 10 ** 6) // 1000 * 1000 for _ in range(n // 2)]
    rng.shuffle(a)
    tests.append(f(a, 0))
    return tests
